function validate([height, positions, directions]) {
  if (!Number.isInteger(height) || height < 1 || height > 1000000) return 'height is between 1 and 10^6.';
  if (positions.length < 1 || positions.length > 100000) return 'positions needs 1 to 10^5 pistons.';
  if (directions.length !== positions.length) return 'directions needs exactly one letter per piston.';
  if (positions.some(p => p < 0 || p > height)) return 'Each position is between 0 and height.';
  if (!/^[UD]+$/.test(directions)) return "directions may contain only 'U' and 'D'.";
  return null;
}

