function maxArea(height, positions, directions) {
  const period = 2 * height;
  const turns = new Array(period + 1).fill(0);
  let area = 0;
  let slope = 0;
  for (let i = 0; i < positions.length; i++) {
    const position = positions[i];
    area += position;
    if (directions[i] === 'U') {
      slope += 1;
      turns[height - position] -= 2;
      turns[period - position] += 2;
    } else {
      slope -= 1;
      turns[position] += 2;
      turns[height + position] -= 2;
    }
  }
  let best = area;
  for (let time = 0; time < period; time++) {
    slope += turns[time];
    area += slope;
    best = Math.max(best, area);
  }
  return best;
}

