function maxArea(height, positions, directions) {
  // Move every piston one step at a time for a whole cycle and add up the positions each second.
  const pos = positions.slice();
  const step = [...directions].map(c => (c === 'U' ? 1 : -1));
  const total = () => pos.reduce((sum, p) => sum + p, 0);
  let best = total();
  for (let second = 1; second <= 2 * height; second++) {
    for (let i = 0; i < pos.length; i++) {
      if (pos[i] === height) step[i] = -1;
      if (pos[i] === 0) step[i] = 1;
      pos[i] += step[i];
    }
    best = Math.max(best, total());
  }
  return best;
}

