function generate(rand, size) {
  const large = size === 'large';
  const height = large ? 500000 + Math.floor(rand() * 500001) : 1 + Math.floor(rand() * 8);
  const n = large ? 2000 : 1 + Math.floor(rand() * 6);
  // Some inputs cluster the pistons on a few starting spots so the total swings widely.
  const spots = Array.from({ length: 1 + Math.floor(rand() * 4) }, () => Math.floor(rand() * (height + 1)));
  const clustered = rand() < 0.4;
  const upShare = rand();
  const positions = [];
  let directions = '';
  for (let i = 0; i < n; i++) {
    const roll = rand();
    const position = roll < 0.1 ? 0 : roll < 0.2 ? height : clustered ? spots[Math.floor(rand() * spots.length)] : Math.floor(rand() * (height + 1));
    positions.push(position);
    directions += rand() < upShare ? 'U' : 'D';
  }
  return [height, positions, directions];
}
